from typing import Dict, Union
def string_to_md5(text: str) -> Union[Dict[str, Union[str, Dict[str, int]]], None]:
    # Given a string 'text', return a dictionary containing:
#     - The original string
#     - Its md5 hash
#     - A frequency histogram of its characters (excluding spaces)
#     - The most frequent character(s) and their count
#     If 'text' is empty, return None.
#     :param text: str - The input string to be processed
#     :return: Dict[str, Union[str, Dict[str, int]]] or None - A dictionary with the processed information, or None if input is empty
#     Examples:
#     >>> string_to_md5('A B C')
#     {'original_string': 'A B C', 'md5_hash': '0ef78513b0cb8cef12743f5aeb35f888', 'character_frequencies': {'A': 1, 'B': 1, 'C': 1}, 'most_frequent': {'A': 1, 'B': 1, 'C': 1}}
#     >>> string_to_md5('')
#     None
#     >>> string_to_md5('Hello world')
#     {'original_string': 'Hello world', 'md5_hash': '3e25960a79dbc69b674cd4ec67a72c62', 'character_frequencies': {'H': 1, 'e': 1, 'l': 3, 'o': 2, 'w': 1, 'r': 1, 'd': 1}, 'most_frequent': {'l': 3}}
#     >>> string_to_md5('password')
#     {'original_string': 'password', 'md5_hash': '5f4dcc3b5aa765d61d8327deb882cf99', 'character_frequencies': {'p': 1, 'a': 1, 's': 2, 'w': 1, 'o': 1, 'r': 1, 'd': 1}, 'most_frequent': {'s': 2}}


    if not text:
        return None
        import hashlib

    md5_hash = hashlib.md5(text.encode()).hexdigest()

    filtered_text = text.replace(" ", "")
    char_freq: Dict[str, int] = {}

    for ch in filtered_text:
        char_freq[ch] = char_freq.get(ch, 0) + 1

    if not char_freq:
        most_freq = {}
    else:
        max_freq = max(char_freq.values())
        most_freq = {k: v for k, v in char_freq.items() if v == max_freq}

    return {
        "original_string": text,
        "md5_hash": md5_hash,
        "character_frequencies": char_freq,
        "most_frequent": most_freq,
    }



