def find_rank(string: str) -> int:
    if not string:
        return -1
    freq = Counter(string)
    distinct_chars = sorted(set(string))
    ans = -1
    for index, char in enumerate(distinct_chars):
        rank = index + 1
        if freq[char] >= rank:
            ans = rank
    return ans

