from collections import defaultdict

def maximum(arr, k):
    if k == 0:
        return []

    freq = defaultdict(int)
    for x in arr:
        freq[x] += 1

    satisfying = [x for x in arr if freq[x] >= abs(x)]

    if not satisfying:
        pad_value = min(arr)
    else:
        pad_value = min(satisfying)

    satisfying.sort()
    result = satisfying[:k]

    if len(result) < k:
        result.extend([pad_value] * (k - len(result)))
        result.sort()

    return result

