def get_row(lst, x):
    coords = []
    for i in range(len(lst)):
        for j in range(len(lst[i])):
            if lst[i][j] == x:
                is_even = (i * j) % 2 == 0
                coords.append((i, j, is_even))

    # First sort by column descending
    sorted_by_column = sorted(coords, key=lambda coord: coord[1], reverse=True)
    # Then sort by row ascending
    sorted_final = sorted(sorted_by_column, key=lambda coord: coord[0])
