def list_analysis(lst):
    """
    Analyze a list of integers and return a dictionary with various properties.
    Includes checking if the list is sorted, duplicate counts, and even/odd digit counts.

    Returns a dictionary with these keys:
    - 'is_sorted': bool indicating if list is sorted in ascending order
    - 'has_duplicates': bool indicating if any number appears more than twice
    - 'even_count': total number of even digits in all numbers
    - 'odd_count': total number of odd digits in all numbers

    Example:
    list_analysis([1, 2, 2, 3]) => {
        'is_sorted': True,
        'has_duplicates': True,
        'even_count': 2,
        'odd_count': 3
    }
    """

    # Initialize analysis dictionary
    result = {
        'is_sorted': False,
        'has_duplicates': False,
        'even_count': 0,
        'odd_count': 0
    }

    # 1. Check if the list is sorted
    if len(lst) >= 1:
        is_sorted = True
        for i in range(1, len(lst)):
            if lst[i-1] > lst[i]:
                is_sorted = False
                break
        result['is_sorted'] = is_sorted

    # 2. Check for duplicates
    if len(lst) >= 1:
        count_digit = {}
        for num in lst:
            if num in count_digit:
                count_digit[num] += 1
                if count_digit[num] > 2:
                    result['has_duplicates'] = True
            else:
                count_digit[num] = 1

    # 3. Count even and odd digits
    if len(lst) >= 1:
        even_count = 0
        odd_count = 0
        for num in lst:
            for digit_char in str(abs(num)):
                digit = int(digit_char)
                if digit % 2 == 0:
                    even_count += 1
                else:
                    odd_count += 1
        result['even_count'] = even_count
        result['odd_count'] = odd_count

    return result

