    memo = {}

    def is_prime(n):
        if n in memo:
            return memo[n]
        if n <= 1:
            memo[n] = False
            return False
        if n <= 3:
            memo[n] = True
            return True
        if n % 2 == 0 or n % 3 == 0:
            memo[n] = False
            return False
        i = 5
        w = 2
        while i * i <= n:
            if n % i == 0:
                memo[n] = False
                return False
            i += w
            w = 6 - w
        memo[n] = True
        return True

