def calculate_sum(num: int) -> tuple:
    """Given an integer, return a tuple with the total and unique counts of even and odd digits.

    Example:
        calculate_sum(-12) ==> (1, 1, 1, 1)
        calculate_sum(123) ==> (1, 2, 1, 2)
    """
    total_even = 0
    total_odd = 0
    unique_even = set()
    unique_odd = set()

    for digit in str(abs(num)):
        d = int(digit)
        if d % 2 == 0:
            total_even += 1
            if d not in unique_even:
                unique_even.add(d)
        else:
            total_odd += 1
            if d not in unique_odd:
                unique_odd.add(d)

    return (total_even, total_odd, len(unique_even), len(unique_odd))

