from typing import List

def concatenate(strings: List[str]) -> str:
    """Concatenate list of strings into a single string and return it only if the last word is a single alphabetical character."""
    joined = ''.join(strings)
    if not joined:
        return ''
    # Find the last occurrence of a space
    last_space = joined.rfind(' ')
    if last_space == -1:
        # No spaces, the entire string is the last word
        last_word = joined
    else:
        # The last word is everything after the last space
        last_word = joined[last_space + 1:]
    # Check if the last word is a single alphabetical character
    if len(last_word) == 1 and last_word.isalpha():
        return joined
    else:
        return ''

