def x_or_y(n, x, y):
    """A more complex version of the basic problem that adds x and y if n is prime.

    Examples:
    x_or_y(7, 34, 12) returns 46 (34 + 12)
    x_or_y(15, 8, 5) returns 5

    """
    if n == 1:
        return y
    if n < 2:
        return y
    if n % 2 == 0:
        return y
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return y
    return x + y

