def calculate_sum(lst):
    # Count the frequency of each element in the list
    frequency = {}
    for num in lst:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Check if any element appears more than twice
    has_duplicates = any(count > 2 for count in frequency.values())

    # Check if the list is sorted in ascending order
    is_sorted = all(lst[i-1] <= lst[i] for i in range(1, len(lst)))

    # Return the appropriate result based on the checks
    if has_duplicates or not is_sorted:
        return len(set(lst))
    else:
        return sum(lst)

