def calculate_largest_divisor(n: int) -> int:
    """Determine if the number can be written as the sum of exactly four positive even numbers and return the largest proper divisor if possible.
    >>> calculate_largest_divisor(8) -> 4
    >>> calculate_largest_divisor(10) -> 5
    >>> calculate_largest_divisor(6) -> 0
    """
    # Check if the number is even and at least 8
    if n % 2 != 0 or n < 8:
        return 0

    # Function to find the smallest prime factor
    def smallest_prime_factor(x: int) -> int:
        if x % 2 == 0:
            return 2
        max_divisor = int(x ** 0.5) + 1
        for i in range(3, max_divisor, 2):
            if x % i == 0:
                return i
        return x  # x is prime

    spf = smallest_prime_factor(n)
    if spf == n:
        return 1  # n is prime, largest proper divisor is 1
    else:
        return n // spf

